<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>الطبقات الجيولوجية للأرض</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: "Segoe UI", Tahoma, Arial, sans-serif;
    background: linear-gradient(160deg, #0b1120 0%, #131b2e 40%, #1a2744 100%);
    color: #e2e8f0;
    min-height: 100vh;
    line-height: 1.8;
  }

  /* ---- Header ---- */
  header {
    text-align: center;
    padding: 3rem 1rem 1rem;
  }
  header h1 {
    font-size: 2.2rem;
    font-weight: 800;
    background: linear-gradient(135deg, #f59e0b, #f97316, #ef4444);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
  header p {
    margin-top: .5rem;
    color: #94a3b8;
    font-size: 1rem;
  }

  /* ---- Earth Diagram ---- */
  .earth-wrap {
    display: flex;
    justify-content: center;
    padding: 2rem 1rem;
  }
  .earth-svg { filter: drop-shadow(0 0 30px rgba(245,158,11,.25)); }

  /* ---- Cards ---- */
  .cards {
    max-width: 900px;
    margin: 0 auto;
    padding: 0 1.5rem 3rem;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 1.5rem;
  }
  .card {
    border-radius: 16px;
    padding: 1.8rem 1.6rem;
    position: relative;
    overflow: hidden;
    transition: transform .25s ease, box-shadow .25s ease;
  }
  .card:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 32px rgba(0,0,0,.4);
  }
  .card h2 {
    font-size: 1.3rem;
    margin-bottom: .3rem;
    display: flex;
    align-items: center;
    gap: .5rem;
  }
  .card .subtitle {
    font-size: .85rem;
    opacity: .7;
    margin-bottom: .8rem;
  }
  .card p { font-size: .95rem; line-height: 1.9; }

  /* Crust card */
  .card.crust {
    background: linear-gradient(135deg, #3f2e18 0%, #292524 100%);
    border: 1px solid #78716c44;
  }
  .card.crust h2 { color: #d4a373; }

  /* Mantle card */
  .card.mantle {
    background: linear-gradient(135deg, #4a1a0a 0%, #2d1215 100%);
    border: 1px solid #9a341244;
  }
  .card.mantle h2 { color: #f97316; }

  /* Core card */
  .card.core {
    background: linear-gradient(135deg, #3b1a00 0%, #1e1008 100%);
    border: 1px solid #b4530944;
  }
  .card.core h2 { color: #fbbf24; }

  .card .dot {
    width: 12px; height: 12px;
    border-radius: 50%;
    display: inline-block;
    flex-shrink: 0;
  }
  .crust .dot { background: #d4a373; }
  .mantle .dot { background: #f97316; }
  .core  .dot { background: #fbbf24; }

  /* ---- Stats Bar ---- */
  .stats {
    max-width: 900px;
    margin: 0 auto 2rem;
    padding: 0 1.5rem;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 1rem;
  }
  .stat {
    background: #ffffff08;
    border: 1px solid #ffffff15;
    border-radius: 12px;
    padding: 1.2rem 1.4rem;
    text-align: center;
  }
  .stat .num {
    font-size: 1.8rem;
    font-weight: 700;
    color: #f59e0b;
  }
  .stat .label {
    font-size: .85rem;
    color: #94a3b8;
    margin-top: .2rem;
  }

  /* ---- Depth Bar Chart ---- */
  .depth-section {
    max-width: 900px;
    margin: 0 auto 3rem;
    padding: 0 1.5rem;
  }
  .depth-section h2 {
    text-align: center;
    font-size: 1.2rem;
    color: #94a3b8;
    margin-bottom: 1.2rem;
  }
  .depth-bar-wrap {
    background: #ffffff08;
    border: 1px solid #ffffff15;
    border-radius: 12px;
    padding: 1.5rem;
  }
  .depth-row {
    display: flex;
    align-items: center;
    margin-bottom: .6rem;
  }
  .depth-row:last-child { margin-bottom: 0; }
  .depth-label {
    width: 110px;
    font-size: .9rem;
    font-weight: 600;
    flex-shrink: 0;
  }
  .depth-track {
    flex: 1;
    height: 28px;
    background: #ffffff0a;
    border-radius: 6px;
    overflow: hidden;
    position: relative;
  }
  .depth-fill {
    height: 100%;
    border-radius: 6px;
    display: flex;
    align-items: center;
    padding-inline-end: .8rem;
    font-size: .8rem;
    font-weight: 700;
    color: #fff;
    transition: width 1.2s ease;
  }
  .depth-fill.crust-fill  { background: linear-gradient(90deg, #d4a373, #a16207); width: 1%; }
  .depth-fill.mantle-fill { background: linear-gradient(90deg, #f97316, #b45309); width: 84%; }
  .depth-fill.outer-fill  { background: linear-gradient(90deg, #fbbf24, #f59e0b); width: 12%; }
  .depth-fill.inner-fill  { background: linear-gradient(90deg, #fef08a, #fbbf24); width: 3%; }

  /* ---- Footer ---- */
  footer {
    text-align: center;
    padding: 2rem 1rem;
    font-size: .8rem;
    color: #475569;
    border-top: 1px solid #ffffff0a;
  }

  @media (max-width: 600px) {
    header h1 { font-size: 1.5rem; }
    .cards { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>

<header>
  <h1>الطبقات الجيولوجية للأرض</h1>
  <p>رحلة إلى قلب كوكبنا — من القشرة إلى النواة</p>
</header>

<!-- ====== Earth Cross-Section SVG ====== -->
<div class="earth-wrap">
  <svg class="earth-svg" width="340" height="340" viewBox="0 0 340 340">
    <defs>
      <radialGradient id="glow" cx="50%" cy="50%" r="50%">
        <stop offset="0%" stop-color="#fef3c7" stop-opacity=".3"/>
        <stop offset="100%" stop-color="#fef3c7" stop-opacity="0"/>
      </radialGradient>
    </defs>
    <!-- Outer glow -->
    <circle cx="170" cy="170" r="170" fill="url(#glow)"/>

    <!-- Crust -->
    <circle cx="170" cy="170" r="168" fill="#8B6914" stroke="#a16207" stroke-width="1"/>
    <!-- Mantle -->
    <circle cx="170" cy="170" r="148" fill="#b91c0c" stroke="#dc2626" stroke-width="1"/>
    <!-- Outer core -->
    <circle cx="170" cy="170" r="72"  fill="#f59e0b" stroke="#fbbf24" stroke-width="1"/>
    <!-- Inner core -->
    <circle cx="170" cy="170" r="30"  fill="#fef08a" stroke="#fde68a" stroke-width="1"/>

    <!-- Labels (radial lines) -->
    <line x1="170" y1="170" x2="290" y2="60" stroke="#e2e8f0" stroke-width=".8" stroke-dasharray="4,3" opacity=".5"/>
    <line x1="170" y1="170" x2="300" y2="130" stroke="#e2e8f0" stroke-width=".8" stroke-dasharray="4,3" opacity=".5"/>
    <line x1="170" y1="170" x2="295" y2="200" stroke="#e2e8f0" stroke-width=".8" stroke-dasharray="4,3" opacity=".5"/>
    <line x1="170" y1="170" x2="270" y2="270" stroke="#e2e8f0" stroke-width=".8" stroke-dasharray="4,3" opacity=".5"/>

    <text x="300" y="55" fill="#d4a373" font-size="12" font-weight="700">القشرة</text>
    <text x="305" y="128" fill="#f97316" font-size="12" font-weight="700">الوشاح</text>
    <text x="302" y="203" fill="#fbbf24" font-size="12" font-weight="700">النواة الخارجية</text>
    <text x="275" y="278" fill="#fef08a" font-size="12" font-weight="700">النواة الداخلية</text>
  </svg>
</div>

<!-- ====== Stats ===== -->
<div class="stats">
  <div class="stat">
    <div class="num">٦٣٧١ كم</div>
    <div class="label">نصف قطر الأرض</div>
  </div>
  <div class="stat">
    <div class="num">٤٥.٤ مليار</div>
    <div class="label">سنة (عمر الأرض)</div>
  </div>
  <div class="stat">
    <div class="num">٥٤٠٠°م</div>
    <div class="label">حرارة النواة المركزية</div>
  </div>
</div>

<!-- ====== Depth Bars ===== -->
<div class="depth-section">
  <h2>نسبة كل طبقة من نصف قطر الأرض</h2>
  <div class="depth-bar-wrap">
    <div class="depth-row">
      <div class="depth-label" style="color:#d4a373">القشرة</div>
      <div class="depth-track"><div class="depth-fill crust-fill" style="width:0.3%">٪٠٫٣</div></div>
    </div>
    <div class="depth-row">
