fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "AUTO"

    val nanosPerSecond = 1_000_000_000L
    val denominator = nanosPerSecond.toDouble() / exposureTimeNs.toDouble()


    if (denominator >= 1.0) {
        return if (denominator == denominator.toLong().toDouble()) {
            "${denominator.toLong()}s"
        } else {
            "${"%.1f".format(denominator)}s"
        }
    }


    val rounded = denominator.toLong().coerceAtLeast(1)
    return "1/${rounded}s"
}

