"""
Chess move generator — normal moves, captures, pawn double pushes, and castling.

Provides:
    legal_moves(fen) -> list[str]   # UCI move strings
    perft(fen, depth) -> int         # leaf nodes at given depth

Does not handle: en passant, promotion, or check/pin legality filtering
(beyond the castling-safety checks). """

from __future__ import annotations
import string


# ---------------------------------------------------------------------------
# Board representation
# ---------------------------------------------------------------------------

EMPTY = 0
WP, WN, WB, WR, WQ, WK = 1, 2, 3, 4, 5, 6
BP, BN, BB, BR, BQ, BK = -1, -2, -3, -4, -5, -6

PIECE_LETTERS = {
    WP: "P", WN: "N", WB: "B", WR: "R", WQ: "Q", WK: "K",
    BP: "p", BN: "n", BB: "b", BR: "r", BQ: "q", BK: "k",
}

# Squre helpers: 0 = a1, 1 = b1, ..., 63 = h8
def sq(file: int, rank: int) -> int:
    return rank * 8 + file

def sq_file(s: int) -> int:
    return s % 8

def sq_rank(s: int) -> int:
    return s // 8

def uci_from(s: int, t: int) -> str:
    return f"{string.ascii_lowercase[sq_file(s)]}{sq_rank(s)+1}" \
           f"{string.ascii_lowercase[sq_file(t)]}{sq_rank(t)+1}"

def uci_to(m: str) -> tuple[int, int]:
    sf, sr, tf, tr = m[0], m[1], m[2], m[3]
    return sq(ord(sf) - ord("a"), int(sr) - 1), \
           sq(ord(tf) - ord("a"), int(tr) - 1)


# ---------------------------------------------------------------------------
# FEN parsing / writing
# ---------------------------------------------------------------------------

def parse_fen(fen: str) -> tuple[list[int], int, str]:
    """Return (board[64], side_to_move, castling_rights) where side is
    +1=white, -1=black and castling_rights is e.g. 'KQkq' or '-'."""
    parts = fen.split()
    board = [EMPTY] * 64
    row_strs = parts[0].split("/")
    rank_idx = 7
    for row_str in row_strs:
        file_idx = 0
        for ch in row_str:
            if ch.isdigit():
                file_idx += int(ch)
            else:
                piece = ch
                mapping = {
                    "P": WP, "N": WN, "B": WB, "R": WR, "Q": WQ, "K": WK,
                    "p": BP, "n": BN, "b": BB, "r": BR, "q": BQ, "k": BK,
                }
                board[sq(file_idx, rank_idx)] = mapping[piece]
                file_idx += 1
        rank_idx -= 1
    side = 1 if parts[1] == "w" else -1
    castling = parts[2] if len(parts) > 2 else "-"
    return board, side, castling

def board_to_fen(board: list[int], side: int, castling: str = "-") -> str:
    """Minimal FEN for internal use."""
    rows = []
    for r in range(7, -1, -1):
        empty = 0
        row = ""
        for f in range(8):
            p = board[sq(f, r)]
            if p == EMPTY:
                empty += 1
            else:
                if empty:
                    row += str(empty)
                    empty = 0
                row += PIECE_LETTERS[p]
        if empty:
            row += str(empty)
        rows.append(row)
    return f"{'/'.join(rows)} {'w' if side == 1 else 'b'} {castling} - 0 1"


# ---------------------------------------------------------------------------
# Attack masks
# ---------------------------------------------------------------------------

# Pre-compute attack bitboards for sliders and knights / king.
def _mask_files_ranks() -> tuple[list[int], list[int]]:
    """Return (file_masks, rank_masks) as integers for each square."""
    file_masks = []
    rank_masks = []
    for s in range(64):
        f = sq_file(s)
        r = sq_rank(s)
        fm = 0
        rm = 0
        for rank in range(8):
            fm |= 1 << sq(f, rank)
        for fi in range(8):
            rm |= 1 << sq(fi, r)
        file_masks.append(fm)
        rank_masks.append(rm)
    return file_masks, rank_masks

FILE_MASKS, RANK_MASKS = _mask_files_ranks()

# Knight moves: delta list
_KNIGHT_DELTAS = [
    -17, -15, -10, -6, 6, 10, 15, 17
]

# King moves: delta list
_KING_DELTAS = [
    -9, -8, -7, -1, 1, 7, 8, 9
]

# Bishop / Queen diagonal + anti-diagonal deltas
_BISHOP_DELTAS = [-9, -7, 7, 9]
_ROOK_DELTAS = [-8, -1, 1, 8]
_QUEEN_DELTAS = [-9, -8, -7, -1, 1, 7, 8, 9]


def _sliding_attacks(sq: int, deltas: list[int], bb: int) -> set[int]:
    """Collect all squares attacked by a slider on *sq* given occupancy *bb*."""
    attacks: set[int] = set()
    f0 = sq_file(sq)
    r0 = sq_rank(sq)
    for d in deltas:
        sf, sr = sq_file(sq + d), sq_rank(sq + d)
        # Must stay on board
        if not (0 <= sf < 8 and 0 <= sr < 8):
            continue
        # Verify the delta is a valid direction for this slider:
        #   rook deltas: straight (same file or same rank)
        #   bishop/queen deltas: diagonal (|df| == |dr| == 1)
        df = abs(sf - f0)
        dr = abs(sr - r0)
        if d in _ROOK_DELTAS:
            if df > 0 and dr > 0:   # not straight
                continue
        elif d in _BISHOP_DELTAS:
            if df != dr:            # not diagonal
                continue
        # For queen, any of the 8 deltas is valid
        # Step outward in this direction
        step = d
        for _ in range(7):
            nxt = sq + step
            nf, nr = sq_file(nxt), sq_rank(nxt)
            if not (0 <= nf < 8 and 0 <= nr < 8):
                break
            # Prevent edge-wrapping
            if d in _ROOK_DELTAS:
                if nf != f0 and nr != r0:
                    break
            elif d in _BISHOP_DELTAS or d in _QUEEN_DELTAS:
                if abs(nf - f0) != abs(nr - r0) and (nf != f0 or nr != r0):
                    break
            attacks.add(nxt)
            if bb & (1 << nxt):
                break
            step += d
    return attacks


def knight_attacks(sq: int) -> set[int]:
    """Non-boundary-checked knight attacks."""
    attacks = set()
    for d in _KNIGHT_DELTAS:
        t = sq + d
        f, r = sq_file(t), sq_rank(t)
        if 0 <= f < 8 and 0 <= r < 8:
            # Knight must actually move like an L, not slip off board edge
            # Check that we didn't wrap: |df| + |dr| == 3
            df, dr = abs(f - sq_file(sq)), abs(r - sq_rank(sq))
            if df + dr == 3:
                attacks.add(t)
    return attacks


def king_attacks(sq: int) -> set[int]:
    attacks = set()
    for d in _KING_DELTAS:
        t = sq + d
        f, r = sq_file(t), sq_rank(t)
        if 0 <= f < 8 and 0 <= r < 8:
            df, dr = abs(f - sq_file(sq)), abs(r - sq_rank(sq))
            if df <= 1 and dr <= 1 and (df + dr > 0):
                attacks.add(t)
    return attacks


def bishop_attacks(sq: int, bb: int) -> set[int]:
    return _sliding_attacks(sq, _BISHOP_DELTAS, bb)

def rook_attacks(sq: int, bb: int) -> set[int]:
    return _sliding_attacks(sq, _ROOK_DELTAS, bb)

def queen_attacks(sq: int, bb: int) -> set[int]:
    return _sliding_attacks(sq, _QUEEN_DELTAS, bb)


# ---------------------------------------------------------------------------
# Attack helpers (needed for castling safety checks)
# ---------------------------------------------------------------------------

def is_square_attacked(board: list[int], target: int, by_side: int) -> bool:
    """Return True if square *target* is attacked by any piece of *by_side*."""
    occ = _bb(board)
    for src in range(64):
        p = board[src]
        if p == EMPTY:
            continue
        if (p > 0) != (by_side > 0):
            continue
        pp = abs(p)
        if pp == 6:
            if target in king_attacks(src):
                return True
        elif pp == 2:
            if target in knight_attacks(src):
                return True
        elif pp == 3:
            if target in bishop_attacks(src, occ):
                return True
        elif pp == 4:
            if target in rook_attacks(src, occ):
                return True
        elif pp == 5:
            if target in queen_attacks(src, occ):
                return True
        elif pp == 1:
            pawn_dir = 1 if by_side == 1 else -1
            pf, pr = sq_file(src), sq_rank(src)
            for delta in [-1, 1]:
                tf, tr = pf + delta, pr + pawn_dir
                if 0 <= tf < 8 and 0 <= tr < 8:
                    if sq(tf, tr) == target:
                        return True
    return False


def _has_castling_right(castling: str, king_sq: int, rook_sq: int) -> bool:
    """Check if the (king_sq, rook_sq) pair has the right in *castling*."""
    rights = {"K": (sq(4, 0), sq(7, 0)),   # white kingside
              "Q": (sq(4, 0), sq(0, 0)),   # white queenside
              "k": (sq(4, 7), sq(7, 7)),   # black kingside
              "q": (sq(4, 7), sq(0, 7)),   # black queenside
              }
    for ch, (ks, rs) in rights.items():
        if ch in castling and ks == king_sq and rs == rook_sq:
            return True
    return False


def _update_castling(castling: str, piece: int, frm: int, to: int) -> str:
    """Remove castling rights when king or rook moves."""
    rights_map = {
        sq(4, 0): {"K", "Q"}, sq(0, 0): {"Q"}, sq(7, 0): {"K"},
        sq(4, 7): {"k", "q"}, sq(0, 7): {"q"}, sq(7, 7): {"k"},
    }
    removed = set()
    removed |= rights_map.get(frm, set())
    removed |= rights_map.get(to, set())
    return "".join(ch for ch in castling if ch not in removed) if castling != "-" else "-"


# ---------------------------------------------------------------------------
# Move generation (raw pseudo-legal, no check filtering)
# ---------------------------------------------------------------------------

def _piece_at(board: list[int], s: int) -> int:
    return board[s]

def _bb(board: list[int]) -> int:
    """Occupancy bitboard."""
    bb = 0
    for s, p in enumerate(board):
        if p != EMPTY:
            bb |= 1 << s
    return bb


def _make_move(board: list[int], frm: int, to: int, castling: str = "-") -> tuple[list[int], int, str]:
    """Return (new_board, new_side, new_castling). No promotion handling.
    Handles castling rook relocation when the move is a castling move."""
    new_board = board[:]
    piece = new_board[frm]
    new_board[frm] = EMPTY
    new_board[to] = piece
    new_castling = _update_castling(castling, piece, frm, to)
    # If this is a castling move, also relocate the rook
    if piece in (WK, BK) and abs(to - frm) == 2:
        rank = frm // 8
        if to > frm:  # kingside: rook from h-file to f-file
            rook_from = sq(7, rank)
            rook_to = sq(5, rank)
        else:          # queenside: rook from a-file to d-file
            rook_from = sq(0, rank)
            rook_to = sq(3, rank)
        rook_piece = new_board[rook_from]
        new_board[rook_from] = EMPTY
        new_board[rook_to] = rook_piece
    return new_board, -piece // abs(piece), new_castling


PAWN_DIRS = {1: 1, -1: -1}  # white moves +8, black moves -8
PAWN_DOUBLE = {1: 16, -1: -16}


def generate_moves(board: list[int], side: int, castling: str = "-") -> list[tuple[int, int]]:
    """Generate all pseudo-legal moves (including castling) as (from, to) tuples."""
    moves: list[tuple[int, int]] = []
    occ = _bb(board)
