    return moves


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def legal_moves(fen: str) -> list[str]:
    """Return all legal moves (including castling) for the side to move in UCI notation."""
    board, side, castling = parse_fen(fen)
    raw = generate_moves(board, side, castling)
    return [uci_from(frm, to) for frm, to in raw]


def perft(fen: str, depth: int) -> int:
    """Standard perft: count leaf nodes at the given depth. perft(0) == 1."""
    if depth == 0:
        return 1
    board, side, castling = parse_fen(fen)
    raw = generate_moves(board, side, castling)
    total = 0
    for frm, to in raw:
        nb, ns, nc = _make_move(board, frm, to, castling)
        child_fen = board_to_fen(nb, ns, nc)
        total += perft(child_fen, depth - 1)
    return total

