                if rook_sq > s:  # kingside
                    step = 1
                else:            # queenside
                    step = -1
                # Path squares between king and rook (exclusive)
                path = []
                path_sq = s + step
                while path_sq != rook_sq:
                    path.append(path_sq)
                    path_sq += step
                # All path squares must be empty
