                        moves.append((s, t1, pp))
                else:
                    moves.append((s, t1))
                # Double push from starting rank
                if r == my_rank_start:
                    t2 = s + pawn_double
                    if 0 <= t2 < 64 and board[t2] == EMPTY:
                        moves.append((s, t2))
            # Normal captures (diagonal)
            for delta in [-1, 1]:
                t = s + pawn_dir * 8 + delta
                tf = sq_file(t)
                tr = sq_rank(t)
                if 0 <= tf < 8 and 0 <= tr < 8:
                    if abs(tf - f) == 1:
                        target = board[t]
                        if target != EMPTY and enemy(target):
                            if tr == promo_rank:
                                for pp in PROMO_PIECES:
                                    moves.append((s, t, pp))
                            else:
                                moves.append((s, t))
            # En passant capture
            if ep_sq != -1:
                ef = sq_file(ep_sq)
                if ef == f - 1 or ef == f + 1:  # adjacent file
                    # EP rank offset: +1 for white, -2 for black
                    ep_rank_offset = 1 if side == 1 else -2
                    if sq_rank(ep_sq) == r + ep_rank_offset:
                        if sq_rank(ep_sq) == promo_rank:
                            for pp in PROMO_PIECES:
                                moves.append((s, ep_sq, pp))
                        else:
                            moves.append((s, ep_sq))
    return moves


