def legal_moves(fen: str) -> list[str]:
    """Return all legal moves (including castling, EP, promotion) for the
    side to move in UCI notation."""
    board, side, castling, ep_sq = parse_fen(fen)
    raw = generate_moves(board, side, castling, ep_sq)
    result = []
    for mv in raw:
        frm, to = mv[0], mv[1]
        promo = mv[2] if len(mv) > 2 else 0
        result.append(uci_from(frm, to, promo))
    return result


def perft(fen: str, depth: int) -> int:
    """Standard perft: count leaf nodes at the given depth. perft(0) == 1."""
    if depth == 0:
        return 1
    board, side, castling, ep_sq = parse_fen(fen)
    raw = generate_moves(board, side, castling, ep_sq)
    total = 0
    for mv in raw:
        frm, to = mv[0], mv[1]
        promo = mv[2] if len(mv) > 2 else 0
        nb, ns, nc, nep = _make_move(board, frm, to, castling, ep_sq, promo)
        child_fen = board_to_fen(nb, ns, nc, nep)
        total += perft(child_fen, depth - 1)
    return total

